# ─── helpers ───────────────────────────────────────────────────────────────
def load_state():
    try: return json.loads(STATE_FILE.read_text(encoding="utf-8"))
    except Exception: return {"completed": False, "runs": 0, "chapter": 0}

def save_state(s):
    try: STATE_FILE.write_text(json.dumps(s), encoding="utf-8")
    except Exception: pass

def run_chapter(key, timeout=None):
    src = SOURCES[key]
    fd, path = tempfile.mkstemp(prefix="v01d_", suffix=".py")
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        f.write(src)
    try:
        proc = subprocess.Popen([sys.executable, path], cwd=tempfile.gettempdir())
        try:   proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            proc.terminate()
            try:    proc.wait(timeout=3)
            except: proc.kill(); proc.wait()
    except Exception as e:
        sys.stderr.write(f"[V01D] error in {key}: {e}\n")
    finally:
        try: os.unlink(path)
        except: pass

